# ai-global-config export
# Sync Cursor / Claude Code / Codex global config from this machine into the repo.

param(
    [switch]$Force
)

$ErrorActionPreference = "Stop"
$RepoRoot = Split-Path -Parent $PSScriptRoot
$Home = $env:USERPROFILE

function Sync-Tree {
    param(
        [string]$Source,
        [string]$Dest,
        [string[]]$Exclude = @()
    )
    if (-not (Test-Path -LiteralPath $Source)) {
        Write-Warning "Skip missing: $Source"
        return
    }
    if (Test-Path -LiteralPath $Dest) {
        if ($Force) {
            Remove-Item -LiteralPath $Dest -Recurse -Force
        } else {
            Write-Warning "Dest exists, use -Force: $Dest"
            return
        }
    }
    $parent = Split-Path -Parent $Dest
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    robocopy $Source $Dest /E /NFL /NDL /NJH /NJS /NC /NS /NP `
        /XD node_modules .git __pycache__ .venv dist `
        /XF *.sqlite *.sqlite-shm *.sqlite-wal auth.json .env .env.local `
        | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "robocopy failed ($LASTEXITCODE): $Source -> $Dest" }
    Write-Host "Synced: $Source -> $Dest"
}

function Copy-FileIfExists {
    param([string]$Source, [string]$Dest)
    if (-not (Test-Path -LiteralPath $Source)) {
        Write-Warning "Skip missing file: $Source"
        return
    }
    $dir = Split-Path -Parent $Dest
    if ($dir -and -not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    Copy-Item -LiteralPath $Source -Destination $Dest -Force
    Write-Host "Copied: $Source -> $Dest"
}

# Skills (Cursor is source of truth)
Sync-Tree -Source (Join-Path $Home ".cursor\skills") -Dest (Join-Path $RepoRoot "skills\cursor")

# Cursor rules
Sync-Tree -Source (Join-Path $Home ".cursor\rules") -Dest (Join-Path $RepoRoot "cursor\rules")

# Cursor hooks / MCP examples (templates only)
Copy-FileIfExists -Source (Join-Path $Home ".cursor\hooks.json") -Dest (Join-Path $RepoRoot "cursor\hooks.json.template")
Copy-FileIfExists -Source (Join-Path $Home ".cursor\mcp.json") -Dest (Join-Path $RepoRoot "cursor\mcp.json.example")

# Claude Code
Copy-FileIfExists -Source (Join-Path $Home ".claude\AGENTS.md") -Dest (Join-Path $RepoRoot "claude\AGENTS.md")
Copy-FileIfExists -Source (Join-Path $Home ".claude\settings.json") -Dest (Join-Path $RepoRoot "claude\settings.json.example")
if (Test-Path -LiteralPath (Join-Path $Home ".claude\hooks")) {
    Sync-Tree -Source (Join-Path $Home ".claude\hooks") -Dest (Join-Path $RepoRoot "claude\hooks")
}

# Codex
Copy-FileIfExists -Source (Join-Path $Home ".codex\AGENTS.md") -Dest (Join-Path $RepoRoot "codex\AGENTS.md")
Copy-FileIfExists -Source (Join-Path $Home ".codex\config.toml") -Dest (Join-Path $RepoRoot "codex\config.toml.example")

# ai-workspace (scripts + memory templates, exclude runtime private state)
$wsScripts = Join-Path $Home ".ai-workspace\scripts"
$wsMemory = Join-Path $Home ".ai-workspace\memory"
$wsDocs = Join-Path $Home ".ai-workspace\docs"
if (Test-Path -LiteralPath $wsScripts) {
    Sync-Tree -Source $wsScripts -Dest (Join-Path $RepoRoot "ai-workspace\scripts")
}
if (Test-Path -LiteralPath $wsMemory) {
    Sync-Tree -Source $wsMemory -Dest (Join-Path $RepoRoot "ai-workspace\memory")
}
if (Test-Path -LiteralPath $wsDocs) {
    Sync-Tree -Source $wsDocs -Dest (Join-Path $RepoRoot "ai-workspace\docs")
}

# manifest
$skillCount = 0
$skillsRoot = Join-Path $RepoRoot "skills\cursor"
if (Test-Path -LiteralPath $skillsRoot) {
    $skillCount = (Get-ChildItem -LiteralPath $skillsRoot -Recurse -Filter "SKILL.md" -File -ErrorAction SilentlyContinue).Count
}
$manifest = @{
    version = "1.0.0"
    exportedAt = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ssK")
    skillCount = $skillCount
    sourceMachine = $env:COMPUTERNAME
} | ConvertTo-Json -Depth 3
Set-Content -LiteralPath (Join-Path $RepoRoot "manifest.json") -Value $manifest -Encoding UTF8

Write-Host "Export complete. Skills: $skillCount"

# One-click install: sync global AI config to user profile (Windows)
$ErrorActionPreference = "Stop"
$RepoRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$Home = $env:USERPROFILE

function Ensure-Dir([string]$Path) {
    if (-not (Test-Path -LiteralPath $Path)) {
        New-Item -ItemType Directory -Path $Path -Force | Out-Null
    }
}

function Copy-Tree([string]$Source, [string]$Dest) {
    if (-not (Test-Path -LiteralPath $Source)) { return }
    Ensure-Dir (Split-Path -Parent $Dest)
    if (Test-Path -LiteralPath $Dest) { Remove-Item -LiteralPath $Dest -Recurse -Force }
    robocopy $Source $Dest /E /NFL /NDL /NJH /NJS /NC /NS /NP | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "Copy failed: $Source" }
    Write-Host "Installed: $Dest"
}

function Link-SkillsJunction([string]$Target, [string]$Link) {
    Ensure-Dir (Split-Path -Parent $Link)
    if (Test-Path -LiteralPath $Link) { Remove-Item -LiteralPath $Link -Recurse -Force }
    cmd /c mklink /J "$Link" "$Target" | Out-Null
    Write-Host "Linked: $Link -> $Target"
}

# Skills hub at ~/.cursor/skills
$cursorSkills = Join-Path $Home ".cursor\skills"
Copy-Tree -Source (Join-Path $RepoRoot "skills\cursor") -Dest $cursorSkills

# Junction Claude + Codex skills to Cursor hub
Link-SkillsJunction -Target $cursorSkills -Link (Join-Path $Home ".claude\skills")
Link-SkillsJunction -Target $cursorSkills -Link (Join-Path $Home ".codex\skills")

# Cursor rules
Copy-Tree -Source (Join-Path $RepoRoot "cursor\rules") -Dest (Join-Path $Home ".cursor\rules")

# Claude / Codex AGENTS
Ensure-Dir (Join-Path $Home ".claude")
Ensure-Dir (Join-Path $Home ".codex")
Copy-Item -LiteralPath (Join-Path $RepoRoot "claude\AGENTS.md") -Destination (Join-Path $Home ".claude\AGENTS.md") -Force -ErrorAction SilentlyContinue
Copy-Item -LiteralPath (Join-Path $RepoRoot "codex\AGENTS.md") -Destination (Join-Path $Home ".codex\AGENTS.md") -Force -ErrorAction SilentlyContinue

# ai-workspace
Copy-Tree -Source (Join-Path $RepoRoot "ai-workspace\scripts") -Dest (Join-Path $Home ".ai-workspace\scripts")
Copy-Tree -Source (Join-Path $RepoRoot "ai-workspace\memory") -Dest (Join-Path $Home ".ai-workspace\memory")
if (Test-Path -LiteralPath (Join-Path $RepoRoot "ai-workspace\docs")) {
    Copy-Tree -Source (Join-Path $RepoRoot "ai-workspace\docs") -Dest (Join-Path $Home ".ai-workspace\docs")
}

Write-Host ""
Write-Host "Done. Restart Cursor / Claude Code / Codex."
Write-Host "Configure secrets per secrets/README.md if present."

# Shared UTF-8 no-BOM file helpers for ai-workspace scripts.
# Usage: . "$PSScriptRoot\Write-Utf8NoBom.ps1"

function Write-Utf8NoBomFile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,
        [Parameter(Mandatory = $true)]
        [string]$Content
    )
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $utf8 = New-Object System.Text.UTF8Encoding $false
    [System.IO.File]::WriteAllText($Path, $Content, $utf8)
}

function Read-Utf8File {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )
    $utf8 = New-Object System.Text.UTF8Encoding $false
    return [System.IO.File]::ReadAllText($Path, $utf8)
}

# Set Windows console to UTF-8 for the current PowerShell session.
# Safe to dot-source from hooks and other scripts (no stdout pollution).

try {
    chcp 65001 | Out-Null
} catch { }

[Console]::InputEncoding = [System.Text.Encoding]::UTF8
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

# Scan a repo for UTF-8 / mojibake / BOM issues.
param(
    [Parameter(Mandatory = $true)]
    [string]$RepoPath,
    [string]$ReportDir = "",
    [switch]$FailOnError
)

$ErrorActionPreference = "Stop"
. (Join-Path $PSScriptRoot "ensure-utf8-console.ps1")
. (Join-Path $PSScriptRoot "Write-Utf8NoBom.ps1")

$root = (Resolve-Path -LiteralPath $RepoPath).Path
if (-not $ReportDir) {
    $ReportDir = Join-Path $root ".encoding-audit"
}
New-Item -ItemType Directory -Path $ReportDir -Force | Out-Null

$textExtensions = @(
    ".md", ".mdc", ".txt", ".json", ".js", ".mjs", ".cjs", ".ts", ".tsx",
    ".jsx", ".css", ".html", ".htm", ".svg", ".xml", ".yml", ".yaml",
    ".ps1", ".cmd", ".sh", ".sql", ".toml", ".env.example"
)
$skipDirs = @(
    "node_modules", ".git", "dist", "build", ".venv", "__pycache__",
    "coverage", ".next", ".turbo", "package-lock.json"
)

$mojibakePatterns = @(
    "鈥?", "ï¿½", "Ã©", "Ã ", "â€™", "â€œ", "â€", "锟斤拷", "�"
)

$issues = New-Object System.Collections.Generic.List[object]
$fileCount = 0

function Test-HasUtf8Bom {
    param([byte[]]$Bytes)
    return ($Bytes.Length -ge 3 -and $Bytes[0] -eq 0xEF -and $Bytes[1] -eq 0xBB -and $Bytes[2] -eq 0xBF)
}

function Test-ValidUtf8 {
    param([byte[]]$Bytes)
    try {
        $enc = New-Object System.Text.UTF8Encoding $false, $true
        [void]$enc.GetString($Bytes)
        return $true
    } catch {
        return $false
    }
}

Get-ChildItem -LiteralPath $root -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
    $rel = $_.FullName.Substring($root.Length).TrimStart("\", "/")
    foreach ($part in $skipDirs) {
        if ($rel -match "(^|[\\/])$([regex]::Escape($part))([\\/]|$)") { return }
    }

    $ext = $_.Extension.ToLowerInvariant()
    if ($textExtensions -notcontains $ext) { return }

    $fileCount++
    $bytes = [System.IO.File]::ReadAllBytes($_.FullName)

    if (Test-HasUtf8Bom -Bytes $bytes) {
        $issues.Add([ordered]@{
            severity = "error"
            kind     = "utf8_bom"
            path     = $rel
            message  = "UTF-8 BOM present; Node.js JSON parse may fail"
        })
    }

    if (-not (Test-ValidUtf8 -Bytes $bytes)) {
        $issues.Add([ordered]@{
            severity = "error"
            kind     = "invalid_utf8"
            path     = $rel
            message  = "Invalid UTF-8 byte sequence"
        })
        return
    }

    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($text.Length -gt 0 -and [int][char]$text[0] -eq 0xFEFF) {
        $text = $text.Substring(1)
    }

    foreach ($pat in $mojibakePatterns) {
        if ($text.Contains($pat)) {
            $issues.Add([ordered]@{
                severity = "warn"
                kind     = "mojibake"
                path     = $rel
                message  = "Possible mojibake pattern: $pat"
            })
            break
        }
    }
}

$errors = @($issues | Where-Object { $_.severity -eq "error" })
$warns = @($issues | Where-Object { $_.severity -eq "warn" })

$summary = [ordered]@{
    repo       = $root
    scannedAt  = (Get-Date).ToString("yyyy-MM-ddTHH:mm:ssK")
    files      = $fileCount
    errorCount = $errors.Count
    warnCount  = $warns.Count
    issues     = $issues
}

$jsonPath = Join-Path $ReportDir "encoding-audit.json"
Write-Utf8NoBomFile -Path $jsonPath -Content ($summary | ConvertTo-Json -Depth 6)

$lines = @(
    "# Encoding audit",
    "",
    "Repo: $root",
    "Files scanned: $fileCount",
    "Errors: $($errors.Count)",
    "Warnings: $($warns.Count)",
    ""
)
if ($errors.Count -gt 0) {
    $lines += "## Errors"
    foreach ($i in $errors) {
        $lines += "- [$($i.kind)] $($i.path) — $($i.message)"
    }
    $lines += ""
}
if ($warns.Count -gt 0) {
    $lines += "## Warnings"
    foreach ($i in $warns) {
        $lines += "- [$($i.kind)] $($i.path) — $($i.message)"
    }
}
Write-Utf8NoBomFile -Path (Join-Path $ReportDir "encoding-audit.md") -Content ($lines -join "`n")

Write-Host "Scanned $fileCount files — errors: $($errors.Count), warnings: $($warns.Count)"
Write-Host "Report: $jsonPath"

if ($FailOnError -and $errors.Count -gt 0) {
    exit 1
}
exit 0

